async function api(path,body,options){if(options)return sendJSON('/api/'+path,body,options);const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json();}catch{throw Error('網路暫時中斷，請保留輸入後重試。');}if(!r.ok){const e=Error(data.error||'操作失敗，請重試。');e.status=r.status;e.fieldErrors=data.fieldErrors;if(r.status===401&&state){persistCapture();saveView();state=null;nav.hidden=true;renderAuth();}throw e;}return data;}
