function momentView(m){const text=m.text?.trim()||m.media.find(a=>a.kind==='audio'&&a.transcript?.trim())?.transcript||'',photo=!text?m.media.find(a=>a.kind==='image'):null,quiet=m.processing?'正在整理成文字…':m.media.some(a=>a.kind==='audio')?'留下一段聲音':m.media.some(a=>a.kind==='video')?'留下一段短片':'留下一個畫面';let hash=0;for(const c of (m.requestId||m.id))hash=(hash*31+c.charCodeAt(0))>>>0;const pending=m.localEntry,action=pending?`data-pending-note="${pending.id}"`:`data-open-moment="${m.id}"`;return `<article class="paper-entry ${photo||text.length>70?'wide-note':''}" data-note="${m.id}"><button class="paper-note paper-${hash%4} ${hash%2?'tilt-right':'tilt-left'} ${photo?'paper-photo':''} ${hash%3===0?'paper-fold':''}"  ${action} aria-label="打開：${esc(text||quiet)}">${photo?`<img src="${photo.data}" alt="家人留下的照片">`:`<span class="paper-copy">${esc(text||quiet)}</span>`}</button><div class="paper-meta"><span>${esc(m.author)}</span><time>${noteTime(m)}</time><small class="${pending?.status==='failed'?'error':''}">${pending?esc(pendingStatus(pending)):'已保存'}</small></div></article>`;}
