 app.querySelector('#generate').onclick=()=>d?showDiary(d.id):generateToday(day);app.querySelector('#update-diary')?.addEventListener('click',()=>generateToday(day));app.querySelector('#refresh-notes').onclick=load;
 const choose=value=>{selectedDate=value;saveView();render();};app.querySelector('#wall-date').onchange=e=>choose(e.target.value||state.today);if(app.querySelector('#today-date'))app.querySelector('#today-date').onclick=()=>choose(state.today);if(app.querySelector('#yesterday'))app.querySelector('#yesterday').onclick=()=>choose(new Date(Date.parse(state.today+'T12:00:00Z')-86400000).toISOString().slice(0,10));if(app.querySelector('#week-date'))app.querySelector('#week-date').onclick=()=>choose('week');if(app.querySelector('#all-dates'))app.querySelector('#all-dates').onclick=()=>choose('all');app.querySelector('#wall-author').onchange=e=>{authorFilter=e.target.value;render();};app.querySelector('#wall-sort').onchange=e=>{sortOrder=e.target.value;render();};app.querySelector('#clear-filters')?.addEventListener('click',()=>{authorFilter='';choose('all');});app.querySelectorAll('[data-author]').forEach(b=>b.onclick=()=>{authorFilter=b.dataset.author;render();});app.querySelectorAll('[data-note-menu]').forEach(b=>b.onclick=()=>{const menu=app.querySelector(`[data-menu="${b.dataset.noteMenu}"]`);menu.hidden=!menu.hidden;b.setAttribute('aria-expanded',String(!menu.hidden));});app.querySelectorAll('[data-pending-note]').forEach(b=>b.onclick=()=>openPending(b.dataset.pendingNote));bindNotes();
