function updateDiaryAvailability(){for(const d of state.family.diaries){const key=state.family.moments.filter(m=>m.date===d.date&&!m.archivedAt).map(m=>(m.revision||1)>1?`${m.id}:v${m.revision}`:m.id).sort().join('|');d.hasNewSources=key!==(d.pending?.sourceKey||d.sourceKey);}}
function captureDay(){return new Intl.DateTimeFormat('en-CA',{timeZone:state.family.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function localMedia(id,index,m){if(m.data)return m.data;const key=id+':'+index;if(!mediaURLs.has(key)&&m.blob)mediaURLs.set(key,URL.createObjectURL(m.blob));return mediaURLs.get(key)||'';}
