function pendingStatus(e){return e.status==='failed'?'尚未保存 · '+(e.conflict?'另存修改':'重試'):e.status==='local'?'正在保留於裝置…':e.status==='uploading'?`已收下，正在保存${e.progress?' '+e.progress+'%':''}`:'已收下，等待保存';}
