function syncCaptureUI(){const timer=document.querySelector('#voice-time');if(timer&&voiceOwner?.phase==='recording')timer.textContent=' '+Math.floor((Date.now()-voiceStarted)/1000)+'秒';}
async function closeComposer(){if(!composerOpen||writeClosing)return;writeClosing=true;try{await persistCapture();const snapshot={requestId:captureId,text:draftText,date:draftDate||captureDay(),media:files.map(f=>({...f})),revision:captureRevision,capturedAt:new Date().toISOString()},revision=captureRevision;composerOpen=false;captureEpoch++;app.querySelector('#capture-sheet')?.remove();setCaptureModal(false);render();if(!snapshot.text.trim()&&!snapshot.media.length){await writeDraft(draftKey(),null);return;}const entry=await queueCapture(snapshot);if(entry.localError){note(entry.error);return;}if(captureId===snapshot.requestId){if(captureRevision===revision){captureId=uid();draftText='';draftDate='';files=[];captureRevision++;await writeDraft(draftKey(),null);localStorage.removeItem(draftKey());}else{captureId=uid();await persistCapture();note('前一則已收下，後續修改仍保留為草稿。');}}}catch(error){note(error.message);}finally{writeClosing=false;if(!composerOpen&&typeof history!=='undefined'&&history.state?.littleDaysWriter)history.back();renderDock();}}
