async function generateToday(date){const targetDate=typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)?date:/^\d{4}-\d{2}-\d{2}$/.test(selectedDate)?selectedDate:state.today;const b=app.querySelector('#generate'),status=app.querySelector('#generation-state');if(b){b.disabled=true;b.textContent='正在整理…';}if(status)status.textContent='正在整理這一天的日記，你可以先離開。';try{await api('generate',{date:targetDate});state=await api('state');const d=state.family.diaries.find(d=>d.date===targetDate);if(d)showDiary(d.id);else{activeView=null;render();note('今天還沒有素材，先留一張紙條吧。');}}catch(e){note(e.message);if(status)status.textContent=e.message;if(b){b.disabled=false;b.textContent='重試整理';}}}
function showDiary(id){bookSelecting=false;tab='diary';activeView={kind:'diary',id};saveView();const d=state.family.diaries.find(d=>d.id===id);app.innerHTML=`<button id="back-today" class="quiet-link">所有日記</button>${d.hasNewSources?'<button id="update-open-diary" class="primary">整理新片刻</button>':''}${diaryView(d)}`;app.querySelector('#update-open-diary')?.addEventListener('click',()=>generateToday(d.date));app.querySelector('#back-today').onclick=()=>{tab='diary';activeView=null;saveView();render();};bindCommon();scrollTo(0,0);}
