function previewBook(){
 bookSelecting=false;let c;try{c=bookSnapshot(state.family,getBookDraft());}catch(e){note(e.message);return renderBooks();}
 activeView={kind:'book-preview'};saveView();app.innerHTML=`<div class="actions"><button id="back-arrange" class="quiet-link">回選日子</button><button id="save-book" class="primary">保存故事集</button></div><p class="hint">預覽 · 尚未保存</p><p id="book-error" class="error" role="alert"></p><button id="refresh-preview" hidden>讀取家人更新，再預覽</button>${bookContent(c)}`;
 app.querySelector('#back-arrange').onclick=renderDaySelection;app.querySelector('#refresh-preview').onclick=async()=>{state=await api('state');previewBook();};bindChapterSources(c);
 const settings=document.createElement('details');settings.className='book-preview-options';const draft=getBookDraft(),photos=draft.diaryIds.flatMap(id=>versionMedia(state.family,state.family.diaries.find(d=>d.id===id).current)).filter(m=>m.kind==='image');settings.innerHTML=`<summary>書名、封面與章節</summary><label>書名<input id="preview-book-title" value="${esc(draft.title)}"></label><label>版型<select id="preview-template">${BOOK_TEMPLATES.map(t=>`<option value="${t.id}" ${draft.template===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label><label>封面照片<select id="preview-cover"><option value="">純文字封面</option>${photos.map((m,i)=>`<option value="${m.key}" ${draft.cover===m.key?'selected':''}>照片 ${i+1}</option>`).join('')}</select></label><ol class="chapter-order">${draft.diaryIds.map((id,i)=>`<li>${esc(state.family.diaries.find(d=>d.id===id).date)} <button data-preview-move="${i}" data-step="-1" ${i===0?'disabled':''}>前移</button><button data-preview-move="${i}" data-step="1" ${i===draft.diaryIds.length-1?'disabled':''}>後移</button></li>`).join('')}</ol>`;app.querySelector('#book-error').after(settings);settings.querySelector('#preview-book-title').oninput=e=>{draft.title=e.target.value;localStorage.setItem(bookDraftKey(),JSON.stringify(draft));app.querySelector('.book-cover h1').textContent=draft.title;};for(const [selector,field] of [['#preview-template','template'],['#preview-cover','cover']])settings.querySelector(selector).onchange=e=>{draft.title=settings.querySelector('#preview-book-title').value;draft[field]=e.target.value;localStorage.setItem(bookDraftKey(),JSON.stringify(draft));previewBook();};settings.querySelectorAll('[data-preview-move]').forEach(b=>b.onclick=()=>{const i=+b.dataset.previewMove,j=i+(+b.dataset.step);[draft.diaryIds[i],draft.diaryIds[j]]=[draft.diaryIds[j],draft.diaryIds[i]];localStorage.setItem(bookDraftKey(),JSON.stringify(draft));previewBook();});renderDock();
 app.querySelector('#save-book').onclick=async e=>{e.target.disabled=true;e.target.textContent='正在保存…';const draft=getBookDraft();draft.title=settings.querySelector('#preview-book-title').value;draft.template=settings.querySelector('#preview-template').value;draft.cover=settings.querySelector('#preview-cover').value;localStorage.setItem(bookDraftKey(),JSON.stringify(draft));const expectedRevisions=Object.fromEntries(c.chapters.map(ch=>[ch.diaryId,ch.number])),shape=JSON.stringify({title:draft.title,diaryIds:draft.diaryIds,template:draft.template,cover:draft.cover,expectedRevisions});if(draft.requestShape!==shape){draft.requestId=uid();draft.requestShape=shape;localStorage.setItem(bookDraftKey(),JSON.stringify(draft));}try{const r=await api('collection',{...draft,expectedRevisions});localStorage.removeItem(bookDraftKey());state=await api('state');activeView=null;bookView(r.collection.id);note('故事集已保存，之後可再打開。');}catch(err){app.querySelector('#book-error').textContent=err.message;if(err.status===409)app.querySelector('#refresh-preview').hidden=false;e.target.disabled=false;e.target.textContent='重試保存';}};
}
function bookView(id){
 bookSelecting=false;activeView={kind:'book',id};saveView();renderDock();const c=state.family.collections.find(c=>c.id===id);app.innerHTML=`<div class="no-print"><button id="back-books" class="quiet-link">回故事集</button><p class="hint">已保存</p><details><summary>其他選項</summary><button id="print">列印／存成 PDF</button><button id="share-book">分享這本故事集</button></details></div>${bookContent(c)}<p class="hint">線上可聽原聲及看短片；PDF包含文字與照片。</p><section id="book-share-panel"></section>`;
 app.querySelector('#back-books').onclick=()=>{activeView=null;saveView();renderBooks();};app.querySelector('#print').onclick=()=>window.print();bindChapterSources(c);
 app.querySelector('#share-book').onclick=()=>{const panel=app.querySelector('#book-share-panel');panel.innerHTML=`<h2>分享範圍</h2><p>只分享「${esc(c.title)}」的這份文字、所選照片、原聲與短片，不包含其他便條、家庭留言或成員資料。持有連結的人可閱讀，7天內有效；可隨時收回。</p><button id="confirm-book-share" class="primary">建立這本書的分享連結</button><p id="book-share-result" role="status"></p>`;panel.querySelector('button').onclick=async e=>{e.target.disabled=true;try{const r=await api('book-share',{id:c.id});const url=location.origin+'/#read='+r.token;panel.querySelector('#book-share-result').innerHTML=`<label>故事集分享連結<input readonly value="${esc(url)}"></label><button id="copy-book-share">複製連結</button><button id="revoke-book-share">收回這份分享</button>`;panel.querySelector('#copy-book-share').onclick=async()=>{try{await navigator.clipboard.writeText(url);note('故事集連結已複製。');}catch{panel.querySelector('input').select();note('請複製選取的連結。');}};panel.querySelector('#revoke-book-share').onclick=async()=>{await api('book-share-revoke',{id:r.id});panel.querySelector('#book-share-result').textContent='這份分享已收回。';};}catch(err){panel.querySelector('#book-share-result').textContent=err.message;e.target.disabled=false;}};};
}
function taskView(t){const status={unread:'未讀',read:'已讀',accepted:'已接手',done:'已完成'}[t.status];const due=new Date(t.dueAt);return `<article class="task"><strong>${esc(t.text)}</strong><p class="byline">${esc(state.members.find(m=>m.id===t.assigneeId)?.name||'家人')} · ${esc(due.toLocaleString('zh-TW',{timeZone:state.family.timezone}))} · ${status} · 僅在 App 內提醒${due<Date.now()&&t.status!=='done'?' · 時間到了':''}</p>${t.assigneeId===state.member.id&&t.status!=='done'?`<div class="actions">${t.status==='unread'?`<button data-id="${t.id}" data-task-status="read">我看到了</button>`:''}${t.status!=='accepted'?`<button data-id="${t.id}" data-task-status="accepted">我來接手</button>`:''}<button data-id="${t.id}" data-task-status="done">已完成</button></div>`:''}</article>`;}
function renderFamily(){const f=state.family;app.innerHTML=`<h1>一起照顧，一起記得</h1><p class="intro">${esc(f.name)} · ${state.members.map(m=>esc(m.name)).join('、')}</p><button id="refresh-family">讀取家人最新消息</button><h2>家裡的話</h2>${f.comments.slice().reverse().map(c=>`<article class="comment"><p class="byline">${esc(c.author)} · ${c.readBy.includes(state.member.id)?'你已讀':'你未讀'}</p><p>${esc(c.text)}</p><small>${c.recipientId?'私人留言・僅作者與'+esc(state.members.find(m=>m.id===c.recipientId)?.name||'收件人')+'可見':'全家可見'} · ${c.readBy.length} 人已讀，不代表已完成</small></article>`).join('')||'<p>留一句話給家人。</p>'}<button id="mark-read">標為我已讀</button><form id="comment"><label for="comment-recipient">誰可以看</label><select id="comment-recipient" name="recipientId"><option value="">全家可見</option>${state.members.filter(m=>m.id!==state.member.id).map(m=>`<option value="${m.id}">只給${esc(m.name)}・私人留言</option>`).join('')}</select><p class="hint">私人留言不會進入全家日記。</p><label for="comment-text">給家人的話</label><textarea id="comment-text" name="text" rows="2" required></textarea><button type="submit">留下留言</button></form><h2>交給家人的事</h2>${f.tasks.map(taskView).join('')||'<p>目前沒有交接事項。</p>'}<form id="task"><label for="task-text">提醒什麼事</label><input id="task-text" name="text" required><div class="two-col"><div><label for="assignee">交給誰</label><select id="assignee" name="assigneeId">${state.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div><div><label for="due">家庭時間</label><input id="due" name="due" type="datetime-local" required></div></div><button type="submit">交給家人</button><p class="hint">僅在 App 內提醒；離開頁面不會響鈴或推播。時間依家庭時區設定。</p></form>${state.member.role==='owner'?`<h2>邀請家人一起</h2><p class="hint">建立一次性邀請碼，交給信任的家人。7天內有效；對方選「加入家人」建立自己的帳號。</p><button id="invite">建立邀請碼</button><p id="invite-result"></p><h2>晚上的故事時間</h2><form id="settings"><label for="evening">每天整理時間</label><input id="evening" type="time" name="evening" step="900" value="${f.evening}" required><label for="timezone">家庭時區</label><select id="timezone" name="timezone">${['Asia/Taipei','Asia/Hong_Kong','Asia/Tokyo','Europe/London','America/Los_Angeles','America/New_York'].map(z=>`<option ${z===f.timezone?'selected':''}>${z}</option>`).join('')}</select><button type="submit">保存故事時間</button><p class="hint">手機關掉仍會整理。有新素材才更新，人工文字另提候選。更改時區不改已排定提醒的實際時刻，只改時間顯示。</p></form>`:''}<details><summary>回收區（可復原）</summary>${f.moments.filter(m=>m.archivedAt&&(m.authorId===state.member.id||state.member.role==='owner')).map(m=>`<p>${esc(momentTitle(m))}<button data-restore-note="${m.id}">復原紙條</button></p>`).join('')||'<p>目前沒有移入回收區的紙條。</p>'}</details><details><summary>把小日子放到手機主畫面</summary><p>iPhone：用 Safari 打開，按分享，再選「加入主畫面」。Android：用 Chrome 的選單選「加入主畫面」或「安裝應用程式」。</p><p class="hint">下次點圖示可回來繼續；登入與草稿保存在這個瀏覽器。這不會開啟系統推播，提醒仍只在頁內顯示。</p></details><h2>試用與自己的記錄</h2><p>30天試用至 ${esc(f.trialEndsAt.slice(0,10))}。目前不收費。</p><p class="hint">399元／月、五位成員為討論起點，尚非販售方案。測試每檔8MB、每次4檔、家庭20MB（含編碼）；每日最多30次AI整理、20次轉寫，手動修改不限次。不按故事數收費。到期後此版仍可閱讀及匯出，正式保存政策待定。</p><button id="export">下載家庭原始資料</button>`;
app.append(document.querySelector('#logout'));app.querySelectorAll('[data-restore-note]').forEach(b=>b.onclick=async()=>{await api('moment-archive',{id:b.dataset.restoreNote,restore:true});await load();});app.querySelector('#refresh-family').onclick=load;app.querySelector('#mark-read').onclick=async()=>{await api('read',{});await load();};for(const name of ['comment','task','settings']){const form=app.querySelector('#'+name);if(form)form.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(form));b.requestId=form.dataset.requestId||(form.dataset.requestId=uid());if(name==='task')b.dueAt=familyInstant(b.due,state.family.timezone);await api(name,b);await load();note('已保存。');}catch(err){note(err.message);e.submitter.disabled=false;}};}const inv=app.querySelector('#invite');if(inv)inv.onclick=async()=>{try{const r=await api('invite',{});const link=location.origin+'/#join='+encodeURIComponent(r.code);app.querySelector('#invite-result').innerHTML=`<label for="family-invite-link">家庭邀請連結</label><input id="family-invite-link" readonly value="${esc(link)}"><button id="copy-invite-link" type="button">複製家庭邀請連結</button><small>這份連結可加入私人家庭，僅交給信任的家人。一次使用，7天內有效。</small><details><summary>手動輸入邀請碼</summary><code>${esc(r.code)}</code></details>`;app.querySelector('#copy-invite-link').onclick=async()=>{try{await navigator.clipboard.writeText(link);note('家庭邀請連結已複製，可貼到 WhatsApp 給信任的家人。');}catch{app.querySelector('#family-invite-link').select();note('請複製已選取的家庭邀請連結。');}};}catch(e){note(e.message);}};app.querySelector('#export').onclick=async()=>{try{const result=await api('export');const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='little-days-family.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){note(e.message);}};}
document.querySelector('#quick-photo-input').onchange=receivePhotos;document.querySelector('#quick-photo-input').oncancel=()=>{photoChoosing=false;};document.querySelector('#header-family').onclick=()=>{if(voiceOwner?.busy)interruptRecording();tab='family';activeView=null;render();};nav.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(captureTransfer)return note('正在保存，請稍候或取消這次傳送。');if(recording)return note('請先停止錄音，再切換頁面。');persistCapture();bookSelecting=false;activeView=null;tab=b.dataset.tab;saveView();render();window.scrollTo(0,0);});document.querySelector('#logout').onclick=async()=>{if(recording)return note('請先停止錄音。');await api('logout',{});files=[];draftText='';captureId=uid();restoredKey='';await load();};window.addEventListener('beforeunload',e=>{if(outbox?.entries.some(e=>e.localError)||captureError.includes('暫存未成功')){e.preventDefault();e.returnValue='';}});load();
